# ── bookkeeping kit: shared helpers (inlined into each node by gen-ext.js) ──
import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"
BK_REQUESTS = "Bookkeeping Requests"


def bk_slug(name):
    s = re.sub(r"[^a-z0-9]+", "-", str(name or "").lower()).strip("-")
    return s[:40].strip("-") or "client"


def bk_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def bk_write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_now_iso(settings):
    return datetime.datetime.now(bk_tz(settings)).replace(microsecond=0).isoformat()


def bk_norm(name):
    s = re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())
    s = re.sub(r"\b(pty|ltd|limited|p/l|the|inc|co)\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def bk_client_for(settings, slug):
    client = bk_read_json(BK_CLIENTS + "/" + slug + ".json")
    if not client:
        return None
    return client


# ── bookkeeping kit: payroll adapter (inlined into payroll nodes by gen-ext.js) ──
# Xero Payroll AU through xero-payroll-au (reads take xero_tenant_id, so each call lands in the client's own
# organisation) and Deputy through deputy. Read-only: the checks list corrections, the payroll officer makes them.
import csv
import io

from openpyxl import Workbook, load_workbook

BK_PAYROLL = "Bookkeeping/Payroll"
BK_PAYRUNS = "Bookkeeping/PayRuns"
BK_PAYROLL_FILES = "Bookkeeping Payroll"
PAYROLL = "xero-payroll-au"
DEPUTY = "deputy"
PAY_WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
PAY_BANDS = ["ordinary", "early", "late", "saturday", "sunday", "public_holiday", "ot_first", "ot_after"]
PAY_BAND_NAMES = {"ordinary": "ordinary", "early": "early (before start of day)", "late": "late (after end of day)",
                  "saturday": "Saturday", "sunday": "Sunday", "public_holiday": "public holiday",
                  "ot_first": "overtime (first hours)", "ot_after": "overtime (after that)"}


def pay_call(tool, tenant_id=None, **args):
    if tenant_id:
        args["xero_tenant_id"] = tenant_id
    exc = None  # bound first for the platform lint (see xero_call)
    try:
        return api.connectors.invoke(server=PAYROLL, tool=tool, args=args)
    except Exception as exc:
        raise RuntimeError("Xero Payroll: " + str(exc)[:500]) from None


def pay_rows(result, key):
    if isinstance(result, dict):
        rows = result.get(key)
        return rows if isinstance(rows, list) else []
    return result if isinstance(result, list) else []


def pay_date(value):
    """Xero Payroll dates arrive as '/Date(1759276800000+0000)/' or ISO; Deputy's as ISO or epoch seconds."""
    s = str(value or "")
    m = re.match(r"/Date\((-?\d+)", s)
    if m:
        return datetime.datetime.fromtimestamp(int(m.group(1)) / 1000, datetime.timezone.utc).date()
    try:
        return datetime.date.fromisoformat(s[:10])
    except ValueError:
        return None


def pay_xero_dt(d):
    return "DateTime(%d,%d,%d)" % (d.year, d.month, d.day)


def pay_period_end(start, kind):
    kind = str(kind or "").upper()
    if kind == "WEEKLY":
        return start + datetime.timedelta(days=6)
    if kind == "FOURWEEKLY":
        return start + datetime.timedelta(days=27)
    if kind in ("MONTHLY", "QUARTERLY"):
        months = 3 if kind == "QUARTERLY" else 1
        y, mo = start.year + (start.month - 1 + months) // 12, (start.month - 1 + months) % 12 + 1
        return datetime.date(y, mo, min(start.day, 28)) - datetime.timedelta(days=1)
    if kind == "TWICEMONTHLY":
        return start + datetime.timedelta(days=14)
    return start + datetime.timedelta(days=13)  # FORTNIGHTLY


def pay_calendar(tenant_id, name):
    """The client's pay calendar by its Xero name: {id, name, type, start, end, payment}, or None."""
    for c in pay_rows(pay_call("list_payroll_calendars", tenant_id), "PayrollCalendars"):
        if bk_norm(c.get("Name")) == bk_norm(name):
            start = pay_date(c.get("StartDate"))
            if not start:
                return None
            return {"id": c.get("PayrollCalendarID"), "name": c.get("Name"), "type": c.get("CalendarType"),
                    "start": str(start), "end": str(pay_period_end(start, c.get("CalendarType"))),
                    "payment": str(pay_date(c.get("PaymentDate")) or "")}
    return None


def pay_prep_date(payment, weekday):
    """The preparation weekday on or before the pay day."""
    target = PAY_WEEKDAYS.index(weekday) if weekday in PAY_WEEKDAYS else 0
    return payment - datetime.timedelta(days=(payment.weekday() - target) % 7)


def pay_timesheets(tenant_id, start, end):
    where = "StartDate>=%s AND EndDate<=%s" % (pay_xero_dt(start), pay_xero_dt(end))
    return pay_rows(pay_call("list_timesheets", tenant_id, where=where), "Timesheets")


def pay_hm(text, default):
    m = re.match(r"(\d{1,2}):(\d{2})", str(text or ""))
    return (int(m.group(1)), int(m.group(2))) if m else default


def pay_link(todo_id, run):
    """Point a WorkQ item at its pay run record, so its form submissions find the pay run."""
    bk_write_json(BK_PAYRUNS + "/" + todo_id + ".json", {"link": run["slug"] + "-" + run["period_start"]})


# ── Open pay runs and watch for timesheets ──


CHASE_PROMPT = (
    "Draft a short, polite email from a payroll officer at a bookkeeping practice to the client's staff member who "
    "exports the timesheets, asking whether this pay period's timesheets are ready in Xero, as payroll is being prepared "
    "today. Plain text, no subject line, sign off as the payroll team. Use only the facts given."
)
SOURCE_WORDS = {"deputy": "Deputy, exported to Xero by the client", "xero": "entered in Xero Payroll",
                "emailed": "emailed timesheets, keyed into Xero by us", "none": "none (salaried staff only)"}

settings = bk_read_json(BK_SETTINGS) or {}
tz_now = datetime.datetime.now(bk_tz(settings))
try:
    # The trigger's own time when it carries one (a scheduled fire time), so a late run behaves like an on-time one.
    if params.get("now"):
        tz_now = datetime.datetime.fromisoformat(str(params.get("now")).replace("Z", "+00:00")).astimezone(bk_tz(settings))
except ValueError:
    pass
only = bk_slug(params.get("client_name") or "") if str(params.get("client_name") or "").strip() else ""
opened = 0
chased = 0
lines = []

for f in (api.files.list(path=BK_PAYROLL) if settings else []):
    if f.get("kind") != "file" or not str(f.get("path", "")).endswith(".json"):
        continue
    ps = bk_read_json(f["path"]) or {}
    slug = ps.get("slug") or ""
    if not slug or (only and slug != only):
        continue
    name = ps.get("name") or slug
    try:
        client = bk_client_for(settings, slug) or {}
        tenant = client.get("xero_tenant_id")
        if not tenant:
            lines.append("- " + name + ": no Xero organisation in its bookkeeping settings")
            continue
        cal = pay_calendar(tenant, ps.get("calendar"))
        if not cal:
            lines.append("- " + name + ": no pay calendar called \"" + str(ps.get("calendar")) + "\" in Xero Payroll")
            continue
        start = datetime.date.fromisoformat(cal["start"])
        end = datetime.date.fromisoformat(cal["end"])
        payment = datetime.date.fromisoformat(cal["payment"]) if cal["payment"] else end
        prep = pay_prep_date(payment, ps.get("prep_day"))
        h, m = pay_hm(ps.get("prep_time"), (9, 0))
        prep_at = datetime.datetime.combine(prep, datetime.time(h, m), tz_now.tzinfo)
        path = BK_PAYRUNS + "/" + slug + "-" + cal["start"] + ".json"
        run = bk_read_json(path)
        if run is None:
            if tz_now < prep_at and not only:
                continue
            period = cal["start"] + " to " + cal["end"]
            item = api.workq.create(
                title=("Pay run: " + name + ", " + period + ", pay day " + str(payment))[:200],
                scope="org",
                description=(
                    "**Pay run for " + name + "**: " + period + ", pay day **" + str(payment) + "** (" + str(cal["name"]) + ").\n\n"
                    "Hours: " + SOURCE_WORDS.get(ps.get("timesheets") or "none", "") + ".\n\n"
                    "1. Make sure new starters and changes (rates, promotions, terminations) are in Xero Payroll.\n"
                    "2. Wait for the timesheets" + (" from " + ps["ts_owner"] if ps.get("ts_owner") else "") + ". I'll say when they're in Xero.\n"
                    "3. Choose **Run the checks** on the Pay run form below. The check compares the hours, rates, penalties, "
                    "leave and reimbursements, lists what to fix and drafts one query email.\n"
                    "4. Fix what it lists in Xero Payroll and run the checks again until they're clear.\n"
                    "5. Choose **Ready for review** to send the review pack to " + (ps.get("reviewer_name") or "the reviewer") + ".\n\n"
                    "The pay guide and this period's reimbursement file go in `" + BK_PAYROLL_FILES + "/" + slug + "` in Knowledge."
                ),
                priority="high",
                due_date=str(payment),
                assignee_ids=[ps["officer_id"]] if ps.get("officer_id") else None,
                labels=["bookkeeping", "payroll", slug],
            )
            api.workq.attach_form(todo_id=item["id"], form_id=params["payrun_form"])
            run = {"slug": slug, "name": name, "tenant_id": tenant, "calendar": cal, "period_start": cal["start"],
                   "period_end": cal["end"], "payment_date": str(payment), "prep_date": str(prep), "item_id": item["id"],
                   "status": "open", "ts_ready": False, "chased": False, "checks": [], "notes": [],
                   "created_at": bk_now_iso(settings)}
            bk_write_json(path, run)
            pay_link(item["id"], run)
            opened += 1
            lines.append("- " + name + ": pay run opened for " + period)
        if run.get("status") in ("done", "cancelled") or run.get("ts_ready") or ps.get("timesheets") == "none":
            continue
        count = len(pay_timesheets(tenant, start, end))
        if count:
            run["ts_ready"] = True
            api.workq.comment(todo_id=run["item_id"], body=("Timesheets are in Xero Payroll (" + str(count) + "). Choose "
                                                            "**Run the checks** on the Pay run form."))
            bk_write_json(path, run)
            lines.append("- " + name + ": timesheets are in Xero")
        elif (ps.get("timesheets") == "deputy" and not run.get("chased") and ps.get("ts_email")
              and tz_now >= prep_at + datetime.timedelta(minutes=int(ps.get("chase_after_minutes") or 60))):
            email = api.ai.generate(prompt=CHASE_PROMPT, input=json.dumps({
                "to": ps.get("ts_owner") or "the timesheet owner", "business": name,
                "pay_period": cal["start"] + " to " + cal["end"], "pay_day": str(payment)}))
            api.workq.comment(todo_id=run["item_id"], body=(
                "The timesheets aren't in Xero Payroll yet. **Draft follow-up to " + (ps.get("ts_owner") or "the client")
                + " (" + ps["ts_email"] + ")** for you to send:\n\n" + str(email)))
            run["chased"] = True
            bk_write_json(path, run)
            chased += 1
            lines.append("- " + name + ": timesheets are late, chase drafted")
    except Exception as exc:
        lines.append("- " + name + ": " + str(exc)[:200])

summary = ("Opened " + str(opened) + " pay run(s), drafted " + str(chased) + " chase(s)."
           + ("\n\n" + "\n".join(lines) if lines else ""))
